:root {
  /* Colors */
  --color-paper-canvas: #fdfcfc;
  --color-frosted-card: #ffffff;
  --color-linen-panel: #f5f3f1;
  --color-onyx-scrim: #0000004d;
  --color-ink: #000000;
  --color-graphite-body: #44403b;
  --color-pebble-caption: #777169;
  --color-ash-whisper: #a59f97;
  --color-sand-hairline: #ebe8e4;
  --color-carbon-hairline: #00000013;
  --color-jet-action: #000000;
  --color-ember-dot: #ff4704;
  --color-cobalt-dot: #0447ff;

  /* Typography — Font Families */
  --font-waldenburg: "Waldenburg", "General Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.385;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0.14px;
  --text-body: 15px;
  --leading-body: 1.467;
  --tracking-body: 0.15px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0.16px;
  --text-subheading: 18px;
  --leading-subheading: 1.444;
  --tracking-subheading: 0.18px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.35;
  --tracking-heading-sm: 0px;
  --text-heading: 32px;
  --leading-heading: 1.125;
  --tracking-heading: 0px;
  --text-heading-lg: 36px;
  --leading-heading-lg: 1.167;
  --tracking-heading-lg: 0px;
  --text-display: 48px;
  --leading-display: 1.083;
  --tracking-display: -0.96px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-40: 40px;
  --spacing-44: 44px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-72: 72px;
  --spacing-96: 96px;
  --spacing-160: 160px;

  /* Layout */
  --layout-page-max-width: 1180px;
  --layout-section-gap: 160px;
  --layout-card-padding: 32px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
  --radius-lg-2: 10px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 16px;
  --radius-sections: 16px;
  --radius-inputs: 12px;
  --radius-inner-tiles: 10px;
  --radius-small-cards: 8px;
  --radius-tags: 4px;
  --radius-small-elements: 2px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-nav: 9999px;
  --radius-images: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 0.5px rgba(0, 0, 0, 0.075);
  --shadow-subtle-2: inset 0 0 0 0.5px rgba(0, 0, 0, 0.1);
  --shadow-sm: 0 0 0 0.5px rgba(0, 0, 0, 0.125), 0 1px 1px rgba(0, 0, 0, 0.04), 0 2px 4px rgba(0, 0, 0, 0.04);
  --shadow-md: inset 0 0 0 1px rgba(0, 0, 0, 0.1);
  --shadow-md-2: inset 0 0 0 1px rgba(255, 255, 255, 0.6);
  --shadow-lg: inset 0 0 0 1.5px rgba(0, 0, 0, 1);

  /* Surfaces */
  --surface-paper-canvas: #fdfcfc;
  --surface-linen-panel: #f5f3f1;
  --surface-frosted-card: #ffffff;
  --surface-onyx-scrim: #0000004d;
  --surface-jet-action: #000000;
}

